# Generated by tools/homebrew_formula.sh in orin-lang/orin-lang; the release workflow opens a PR with each new version.
# v0.1.0-alpha.2 was published before the move to orin-lang/orin-lang, so its package is still downloaded
# from the old repository; the next release replaces this URL.
class Orin < Formula
  desc "Compiler for Orin, a statically typed language with verified contracts"
  homepage "https://github.com/orin-lang/orin-lang"
  url "https://github.com/HenrySchwerdt/orin/releases/download/v0.1.0-alpha.2/orin-0.1.0-alpha.2-macos-arm64.tar.gz"
  version "0.1.0-alpha.2"
  sha256 "ea57894c610ec3b496ed6fdaec2d0f887f7631157ca68e5b6fc0d7be26eab761"
  license "MIT"

  depends_on arch: :arm64
  depends_on :macos

  def install
    # The release package is relocatable: bin/orin finds libexec/ and lib/orin/ relative to itself, so the whole
    # package goes to libexec and bin/orin is a wrapper that execs the real launcher by its path.
    libexec.install Dir["*"]
    bin.write_exec_script libexec/"bin/orin"
  end

  test do
    # 0.1.0-alpha.2 predates `orin doctor`, `orin run` and `orin build`; the next generated formula tests those.
    assert_equal version.to_s, shell_output("#{bin}/orin --version").strip
    (testpath/"hello.or").write <<~ORIN
      function main(): void {
        console.log("Hello from Homebrew!");
      }
    ORIN
    system bin/"orin", "check", "hello.or"
  end
end
